do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total from public.prompts where catalog_version = 'v2.1';
  if v_total < 80 then
    raise exception 'Lot 3 incomplet : % raccourcis importes au lieu de 80.', v_total;
  end if;
end $ctrl$;

drop table lot_prompts;
